args.sparql:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?paternalGrandmother ?paternalGrandmotherLabel WHERE {
  dbr:Archduchess_Dolores_of_Austria dbp:father ?father .
  ?father dbp:mother ?paternalGrandmother .
  OPTIONAL { ?paternalGrandmother rdfs:label ?paternalGrandmotherLabel . FILTER (langMatches(lang(?paternalGrandmotherLabel), "EN")) }
}
LIMIT 10

